  ["50624d20c9acc976"] = { "Il peso di un'ascia, il grido di battaglia dei tuoi alleati, gli schizzi di sangue in faccia. Ecco ciò che brama un guerriero, {name}. Mi farò strada nelle ⟦The Barrens=Savane⟧ a colpi di spada, in nome dell'⟦Horde=Orda⟧.", "." },
  ["506d41844d8c249e"] = { "Cerchi addestramento nell'arte del combattimento armato?", "." },
  ["506f1064a78c71b9"] = { "Sappiamo perché?", "." },
  ["507c889f221aa5ef"] = { "Jin'rokh, mi serve aiuto per recuperare un pezzo della mia Vindicator's Battlegear.", "." },
  ["5084e1037f7e4dcc"] = { "Non sono qui per onore, {name}. Sono qui per l'orgoglio di un orco.\n\nSe non avessi respinto le avances di Belgrom, di certo sarei ancora a Orgrimmar a occuparmi di faccende serie.\n\nIl suo debole per le donne è noto a molte guerriere di Durotar, ma questo non gli impedisce di fare il seduttore.\n\nPer sua fortuna non ha insistito ancora a lungo con me: gli sarebbe mancato ben più delle dita delle mani.", "." },
  ["50893d2b328d942b"] = { "Noi sente e obbedisce.", "." },
