  ["508a24a3120446ae"] = { "Ehm... scusa il disturbo, ma potrei rivedere il libro mastro di Goodsteel... se non lo stai usando.", "." },
  ["508b27fa602c124a"] = { "Tieniti <pronto/pronta>, {name}. Sento il consiglio che ritorna. Prepariamo l'imboscata!", "." },
