  ["50953898f63febd2"] = { "Leggi il tomo che ho posato davanti a te e pronuncia le parole ad alta voce.", "." },
  ["5099ed03ed043a7e"] = { "{name}, come posso far progredire il tuo addestramento agli occhi della Madre Terra?", "." },
  ["50a5a496a95d605d"] = { "Il capitano Balinda Stonehearth guida le forze dell'⟦Alliance=Alleanza⟧ in prima linea. Ha la sua base all'⟦Stonehearth Outpost=Avamposto di Cordipietra⟧, nella parte settentrionale del ⟦Field of Strife=Pian della Discordia⟧.\n\nBalinda è stata uccisa.", "." },
