  ["50bff56d0d975b0d"] = { "%s comincia a lamentarsi e a ruggire contro Terenthis, battendo le zampe a terra.", "." },
  ["50c1ecc8208c7b48"] = { "Non aver paura della spada, <pivello/pivella>. È il montone che ti frega!", "." },
